using Asp.Versioning;using CashFlow.Launch.Api;using CashFlow.Launch.Domain.Interfaces;using CashFlow.Launch.Infrastructure.Context;using CashFlow.Launch.Infrastructure.Extensions;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;using System.Text;
var builder=WebApplication.CreateBuilder(args);var jwtKey=builder.Configuration["Jwt:Key"]!;builder.Services.AddHttpContextAccessor();builder.Services.AddScoped<ITenantContext,HttpTenantContext>();builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidateAudience=true,ValidateIssuerSigningKey=true,ValidateLifetime=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidAudience=builder.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey))});builder.Services.AddAuthorization(o=>o.FallbackPolicy=new AuthorizationPolicyBuilder().RequireAuthenticatedUser().RequireClaim("group_id").Build());builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="CashFlow API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});builder.Services.AddApiVersioning(o=>{o.DefaultApiVersion=new ApiVersion(1,0);o.AssumeDefaultVersionWhenUnspecified=true;o.ReportApiVersions=true;});builder.Services.AddLaunchInfrastructure(builder.Configuration.GetConnectionString("DefaultConnection")!);var app=builder.Build();using(var scope=app.Services.CreateScope()){scope.ServiceProvider.GetRequiredService<CashFlowDbContext>().Database.Migrate();}if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();